using System;
using System.Collections.Generic;
using Astrea.RunModifiers;
using DG.DemiLib;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.DailyRun;

[CreateAssetMenu(fileName = "DailyRunHandler", menuName = "Data/DailyRunHandler", order = 0)]
public class DailyRunHandler : ScriptableObject
{
	[Header("Fixed Modifiers")]
	[SerializeField]
	private IntRange amountOfDiceToRemoveFromDicePoolRange;

	[SerializeField]
	private IntRange amountOfDiceToAddDicePoolRange;

	[SerializeField]
	private DiceTier[] diceTiersToAddToDicePool;

	[Header("Assets")]
	[SerializeField]
	private CharactersList charactersList;

	[SerializeField]
	private PlayerDiceInventoryData dicePool;

	[SerializeField]
	private DicesRewardsListsList dicesRewardsListsList;

	[SerializeField]
	private DiceRewardSettings diceRewardSettings;

	[SerializeField]
	private RandomVirtuesPool randomVirtuesPool;

	[SerializeField]
	private RunModifiersHandler runModifiersHandler;

	[SerializeField]
	private Character anyCharacter;

	public List<RunModifier> dailyRunRunModifiers = new List<RunModifier>();

	private DateTime startingDateTime => DateTime.UtcNow.Date;

	public DateTime StartingDateTime => startingDateTime;

	public RunModifiersHandler RunModifiersHandler => runModifiersHandler;

	public List<RunModifier> DailyRunRunModifiers => dailyRunRunModifiers;

	public void SetupDailyRun(bool randomizeSeedDebug)
	{
		ReferenceSingleton<AssetsReference>.Instance.GameController.SetIsDailyRun(value: true);
		int unityEngineRandomInitStateSeed = (int)(DateTimeOffset.UtcNow.Date - new DateTime(2024, 4, 4)).TotalDays;
		if (randomizeSeedDebug)
		{
			unityEngineRandomInitStateSeed = RandomUtilities.RandomInt(0, 99999999);
		}
		RandomUtilities.SetUnityEngineRandomInitStateSeed(unityEngineRandomInitStateSeed);
		int num = RandomUtilities.RandomIntWithSeed(99999999);
		RandomUtilities.SetUnityEngineRandomInitStateSeed(num);
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.RunSeedIntReference.SetValue(num);
		Character[] array = charactersList.charactersList;
		List<Character> list = new List<Character>();
		for (int i = 0; i < array.Length; i++)
		{
			if (array[i] != anyCharacter)
			{
				list.Add(array[i]);
			}
		}
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.SetCurrentCharacter(list.PickRandom());
		dailyRunRunModifiers = runModifiersHandler.GetRandomizedRunModifiers(dailyRun: true);
		SetupDicePool();
		randomVirtuesPool.SetupVirtues(dailyRunRunModifiers);
	}

	[Button(null)]
	private void SetupDicePool()
	{
		dicesRewardsListsList.PopulateAnyAndCurrentCharacterUnlockedDiceTierDiceList(dailyRun: true);
		dicePool.OnResetToStartRunState();
		ChangeDiceFromDicePool();
	}

	private void ChangeDiceFromDicePool()
	{
		int count = RandomUtilities.RandomIntWithSeed(amountOfDiceToRemoveFromDicePoolRange.min, amountOfDiceToRemoveFromDicePoolRange.max + 1);
		List<Dice> list = dicePool.GetAllDices().PickRandom(count);
		for (int i = 0; i < list.Count; i++)
		{
			dicePool.DecreaseDiceAmount(list[i], 1);
		}
		AddRandomDiceToDicePool(RandomUtilities.RandomIntWithSeed(amountOfDiceToAddDicePoolRange.min, amountOfDiceToAddDicePoolRange.max + 1));
	}

	public void AddRandomDiceToDicePool(int amountOfDiceToAddDicePool, DiceTier diceTierToPick = null)
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < amountOfDiceToAddDicePool; i++)
		{
			list.Add(GetRandomDiceWithRandomChanceOfBeingCharacterDice(diceTierToPick));
		}
		for (int j = 0; j < list.Count; j++)
		{
			dicePool.IncreaseDiceAmount(list[j], 1, insertAsFirst: true);
		}
	}

	public Dice GetRandomDiceWithRandomChanceOfBeingCharacterDice(DiceTier diceTierToPick = null)
	{
		List<Dice> list = new List<Dice>();
		List<Dice> list2 = new List<Dice>();
		if (diceTierToPick != null)
		{
			list.AddRange(dicesRewardsListsList.GetCurrentCharacterUnlockedDiceTierDiceList(diceTierToPick).diceList.Duplicate());
			list2.AddRange(dicesRewardsListsList.GetAnyCharacterUnlockedDiceTierDiceList(diceTierToPick).diceList.Duplicate());
		}
		else
		{
			for (int i = 0; i < diceTiersToAddToDicePool.Length; i++)
			{
				list.AddRange(dicesRewardsListsList.GetCurrentCharacterUnlockedDiceTierDiceList(diceTiersToAddToDicePool[i]).diceList.Duplicate());
				list2.AddRange(dicesRewardsListsList.GetAnyCharacterUnlockedDiceTierDiceList(diceTiersToAddToDicePool[i]).diceList.Duplicate());
			}
		}
		if (RandomUtilities.RandomChanceWithSeed(diceRewardSettings.SpecificCharDicePercentage))
		{
			return list.PickRandom();
		}
		return list2.PickRandom();
	}

	public TimeSpan GetTimeLeft()
	{
		return TimeSpan.FromHours(24.0) - DateTime.UtcNow.TimeOfDay;
	}

	public void StartDailyRunButtonPressed()
	{
		runModifiersHandler.ActiveRunModifiers = dailyRunRunModifiers.Duplicate();
		ReferenceSingleton<AssetsReference>.Instance.GameController.NewGame();
	}
}
